"""Print the rota for an availability file."""
import sys

from rota.availability import DAYS, parse_availability
from rota.planner import assign


def main(argv):
    if len(argv) != 1:
        print("usage: python3 -m rota AVAILABILITY_FILE", file=sys.stderr)
        return 2
    try:
        with open(argv[0], encoding="utf-8") as handle:
            people = parse_availability(handle.read())
    except (OSError, ValueError) as err:
        print(f"error: {err}", file=sys.stderr)
        return 1
    rota = assign(people)
    for day in DAYS:
        print(f"{day}: {', '.join(rota[day])}")
    return 0


raise SystemExit(main(sys.argv[1:]))
"""Reading availability: one line per person, `NAME: day, day, ...`."""

DAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")


def parse_availability(text):
    """Return {name: set of days}."""
    people = {}
    for number, line in enumerate(text.splitlines(), start=1):
        if not line.strip():
            continue
        name, _, rest = line.partition(":")
        days = {day.strip() for day in rest.split(",") if day.strip()}
        for day in sorted(days):
            if day not in DAYS:
                raise ValueError(f"line {number}: unknown day {day!r}; days are written mon, tue, wed, thu, fri, sat, sun")
        people[name.strip()] = days
    return people
