import unittest

from rota.planner import assign, pick_for_day


class PlannerTests(unittest.TestCase):
    def test_limits_people_per_day(self):
        people = {"a": {"mon"}, "b": {"mon"}, "c": {"mon"}}
        self.assertEqual(len(assign(people)["mon"]), 2)

    def test_empty_day_is_an_empty_list(self):
        self.assertEqual(assign({"a": {"mon"}})["tue"], [])

    def test_rotates_in_name_order(self):
        everyone = {"mon", "tue", "wed", "thu"}
        people = {"cy": everyone, "ana": everyone, "bo": everyone}
        rota = assign(people)
        self.assertEqual(rota["mon"], ["ana", "bo"])
        self.assertEqual(rota["tue"], ["cy", "ana"])
        self.assertEqual(rota["wed"], ["bo", "cy"])
        self.assertEqual(rota["thu"], ["ana", "bo"])

    def test_skips_unavailable_people_and_carries_on(self):
        people = {
            "ana": {"mon", "tue"},
            "bo": {"tue"},
            "cy": {"mon", "tue"},
        }
        rota = assign(people)
        self.assertEqual(rota["mon"], ["ana", "cy"])
        self.assertEqual(rota["tue"], ["ana", "bo"])

    def test_same_result_every_run(self):
        people = {n: {"mon", "tue", "wed"} for n in "edcba"}
        self.assertEqual(assign(people), assign(dict(reversed(list(people.items())))))

    def test_default_is_two_per_day(self):
        people = {n: {"mon"} for n in "abcd"}
        self.assertEqual(assign(people)["mon"], ["a", "b"])

    def test_no_people_gives_empty_rota(self):
        self.assertEqual(assign({})["mon"], [])

    def test_pick_for_day_wraps_and_returns_next_start(self):
        people = {"a": {"mon"}, "b": {"mon"}, "c": {"mon"}}
        picked, next_start = pick_for_day(["a", "b", "c"], people, "mon", 2, 2)
        self.assertEqual(picked, ["c", "a"])
        self.assertEqual(next_start, 1)

    def test_pick_for_day_keeps_start_when_nobody_available(self):
        picked, next_start = pick_for_day(["a"], {"a": {"tue"}}, "mon", 0, 2)
        self.assertEqual((picked, next_start), ([], 0))


if __name__ == "__main__":
    unittest.main()

import csv
import io
import unittest

from rota.availability import DAYS
from rota.export import rota_to_csv, write_csv


def read_rows(text):
    return list(csv.reader(io.StringIO(text, newline="")))


class ExportTests(unittest.TestCase):
    def test_header_then_one_row_per_day(self):
        rows = read_rows(rota_to_csv({"mon": ["ana", "bo"]}))
        self.assertEqual(rows[0], ["day", "people"])
        self.assertEqual([row[0] for row in rows[1:]], list(DAYS))

    def test_people_are_joined_in_one_cell(self):
        rows = read_rows(rota_to_csv({"mon": ["ana", "bo"], "tue": ["cy"]}))
        self.assertEqual(rows[1], ["mon", "ana; bo"])
        self.assertEqual(rows[2], ["tue", "cy"])

    def test_empty_or_missing_day_has_blank_people(self):
        rows = read_rows(rota_to_csv({"mon": []}))
        self.assertEqual(rows[1], ["mon", ""])
        self.assertEqual(rows[2], ["tue", ""])

    def test_names_with_commas_and_quotes_survive(self):
        rows = read_rows(rota_to_csv({"mon": ['Smith, Al', 'Bo "B"']}))
        self.assertEqual(rows[1], ["mon", 'Smith, Al; Bo "B"'])

    def test_write_csv_writes_to_a_file_handle(self):
        buffer = io.StringIO(newline="")
        write_csv({"mon": ["ana"]}, buffer)
        self.assertTrue(buffer.getvalue().startswith("day,people"))


if __name__ == "__main__":
    unittest.main()

